sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.date = new Date();   // the server already loads today's data on first load

  c.load = function() {
    if (!c.date) return;
    var d = c.date;
    var iso = d.getFullYear() + '-' +
              ('0' + (d.getMonth() + 1)).slice(-2) + '-' +
              ('0' + d.getDate()).slice(-2);
    c.server.get({ action: 'load', date: iso });
  };
};

sp_widget.script:
(function() {
  var P = gs.getCurrentScopeName();

  function isTrue(v) { return v == '1' || v == 'true'; }
  function timeOnly(dv) { return dv.split(' ').slice(1).join(' '); }

  // Date being viewed (yyyy-MM-dd). Default: today in the user's time zone.
  var day = (input && input.date) ? String(input.date) : '';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day))
    day = new GlideDateTime().getLocalDate().getValue();

  // 1. Banner: holiday, or no Business Day record
  var hol = new GlideRecord(P + '_calendar_day');
  hol.addQuery('calendar_date', day);
  hol.addQuery('type', 'holiday');
  hol.setLimit(1);
  hol.query();

  var biz = new GlideRecord(P + '_calendar_day');
  biz.addQuery('calendar_date', day);
  biz.addQuery('type', 'business_day');
  biz.setLimit(1);
  biz.query();

  data.showBanner = hol.hasNext() || !biz.hasNext();

  // 2. Wide UTC search window (1 day before to 2 days after); exact filtering is done by local date below
  var from = new GlideDateTime(day + ' 00:00:00');
  from.addDaysUTC(-1);
  var to = new GlideDateTime(day + ' 00:00:00');
  to.addDaysUTC(2);

  // 3. Rooms with an unavailable period overlapping this date
  var unavailable = {};
  var u = new GlideRecord(P + '_room_unavailability');
  u.addQuery('unavailable_from', '<', to.getValue());
  u.addQuery('unavailable_to', '>', from.getValue());
  u.query();
  while (u.next()) {
    var uf = new GlideDateTime(u.getValue('unavailable_from')).getLocalDate().getValue();
    var ut = new GlideDateTime(u.getValue('unavailable_to')).getLocalDate().getValue();
    if (uf <= day && ut >= day)
      unavailable[u.getValue('meeting_room')] = true;
  }

  // 4. Scheduled meetings on this date, grouped by room (time only)
  var meetings = {};
  var m = new GlideRecord(P + '_scheduled_meeting');
  m.addQuery('state', 'scheduled');
  m.addQuery('start_time', '>=', from.getValue());
  m.addQuery('start_time', '<', to.getValue());
  m.orderBy('start_time');
  m.query();
  while (m.next()) {
    var md = new GlideDateTime(m.getValue('start_time')).getLocalDate().getValue();
    if (md != day) continue;
    var rid = m.getValue('meeting_room');
    if (!meetings[rid]) meetings[rid] = [];
    meetings[rid].push(timeOnly(m.getDisplayValue('start_time')) + ' - ' + timeOnly(m.getDisplayValue('end_time')));
  }

  // 5. Build the room list
  data.rooms = [];
  var r = new GlideRecord(P + '_meeting_room');
  r.orderBy('name');
  r.query();
  while (r.next()) {
    var fac = [];
    if (isTrue(r.getValue('tv_conference'))) fac.push('TV Conference');
    if (isTrue(r.getValue('projector'))) fac.push('Projector');
    if (isTrue(r.getValue('white_board_and_markers'))) fac.push('White Board and Markers');
    var id = r.getUniqueValue();
    data.rooms.push({
      name: r.getValue('name'),
      capacity: r.getValue('seating_capacity'),
      accessibility: r.getDisplayValue('accessibility'),
      facilities: fac.length ? fac.join(', ') : 'None',
      status: unavailable[id] ? 'Unavailable' : 'Available',
      meetings: meetings[id] || []
    });
  }
})();
